/* @autogenerated */
import { collectRefs, compact, dependentsOf, matchesQuery, replaceValue } from './offline-ops';
import { isNetworkError, OfflineOp } from './offline.model';

function op(seq: number, kind: OfflineOp['kind'], repo: string, key: string, payload?: any): OfflineOp {
  return { seq, kind, repo, key, payload, scope: 's', status: 'pending', createdAt: seq };
}

describe('offline-ops', () => {
  describe('collectRefs', () => {
    it('collects $ref values and local files at any depth', () => {
      const refs = collectRefs({
        name: 'x',
        model: { $ref: 'm1', $id: 'internal' },
        list: [{ $ref: 'm2' }],
        photo: 'offline-file://f1',
        when: new Date(),
      });
      expect(refs.sort()).toEqual(['f1', 'm1', 'm2']);
    });
  });

  describe('replaceValue', () => {
    it('replaces a string everywhere without touching dates', () => {
      const when = new Date();
      const result = replaceValue({ a: 'old', b: ['old', 'x'], when }, 'old', 'new');
      expect(result).toEqual({ a: 'new', b: ['new', 'x'], when });
      expect(result.when).toBe(when);
    });
  });

  describe('dependentsOf', () => {
    it('blocks later changes of the same entity', () => {
      const ops = [op(1, 'add', 'site', 's1'), op(2, 'update', 'site', 's1'), op(3, 'add', 'site', 's2')];
      const deps = dependentsOf(ops, [ops[0]]);
      expect([...deps.keys()]).toEqual([2]);
      expect(deps.get(2)).toBe(1);
    });

    it('blocks transitively what references a failed creation', () => {
      const ops = [
        op(1, 'add', 'site', 's1'),
        op(2, 'add', 'floor', 'f1', { site: { $ref: 's1' } }),
        op(3, 'patch', 'floor', 'f1', { name: 'x' }),
        op(4, 'add', 'device', 'd1', { floor: { $ref: 'f1' } }),
        op(5, 'add', 'device', 'd2', { floor: { $ref: 'other' } }),
      ];
      const deps = dependentsOf(ops, [ops[0]]);
      expect([...deps.keys()]).toEqual([2, 3, 4]);
      expect(deps.get(4)).toBe(1);
    });

    it('blocks what uses a failed attachment', () => {
      const ops = [op(1, 'file', 'device', 'file1'), op(2, 'add', 'device', 'd1', { photo: 'offline-file://file1' })];
      expect([...dependentsOf(ops, [ops[0]]).keys()]).toEqual([2]);
    });

    it('does not block references to entities updated (not created) by the failed op', () => {
      const ops = [op(1, 'update', 'site', 's1'), op(2, 'add', 'floor', 'f1', { site: { $ref: 's1' } })];
      expect(dependentsOf(ops, [ops[0]]).size).toBe(0);
    });
  });

  describe('compact', () => {
    it('merges an update into the pending creation', () => {
      const queue = [op(1, 'add', 'site', 's1', { name: 'a' })];
      const plan = compact(queue, op(0, 'update', 'site', 's1', { name: 'b' }));
      expect(plan.append).toBeUndefined();
      expect(plan.replace[0].kind).toBe('add');
      expect(plan.replace[0].payload).toEqual({ name: 'b' });
    });

    it('merges a patch into the previous patch', () => {
      const queue = [op(1, 'patch', 'site', 's1', { a: 1 })];
      const plan = compact(queue, op(0, 'patch', 'site', 's1', { b: 2 }));
      expect(plan.replace[0].payload).toEqual({ a: 1, b: 2 });
    });

    it('turns a patch into an update when a full update follows', () => {
      const queue = [op(1, 'patch', 'site', 's1', { a: 1 })];
      const plan = compact(queue, op(0, 'update', 'site', 's1', { a: 2, b: 3 }));
      expect(plan.replace[0].kind).toBe('update');
      expect(plan.replace[0].payload).toEqual({ a: 2, b: 3 });
    });

    it('drops everything when an entity created offline is deleted', () => {
      const queue = [op(1, 'add', 'site', 's1'), op(2, 'patch', 'site', 's1', { a: 1 })];
      const plan = compact(queue, op(0, 'delete', 'site', 's1'));
      expect(plan.append).toBeUndefined();
      expect(plan.remove).toEqual([1, 2]);
    });

    it('keeps the delete of an existing entity, with the first base', () => {
      const queue = [{ ...op(1, 'update', 'site', 's1', { a: 1 }), base: { a: 0 } }];
      const plan = compact(queue, op(0, 'delete', 'site', 's1'));
      expect(plan.remove).toEqual([1]);
      expect(plan.append?.kind).toBe('delete');
      expect(plan.append?.base).toEqual({ a: 0 });
    });

    it('does not merge if the change references something created later', () => {
      const queue = [op(1, 'add', 'floor', 'f1', {}), op(2, 'add', 'site', 's9', {})];
      const plan = compact(queue, op(0, 'update', 'floor', 'f1', { site: { $ref: 's9' } }));
      expect(plan.append).toBeDefined();
      expect(plan.replace.length).toBe(0);
    });
  });

  describe('matchesQuery', () => {
    const item = { uid: 'd1', name: 'Router A', projectDevice: { $ref: 'p1' }, kind: 'x' };

    it('matches equality, plural lists, keys and search', () => {
      expect(matchesQuery(item, { limit: 10 }, 'uid')).toBeTrue();
      expect(matchesQuery(item, { kind: 'x' }, 'uid')).toBeTrue();
      expect(matchesQuery(item, { projectDevices: ['p2', 'p1'] }, 'uid')).toBeTrue();
      expect(matchesQuery(item, { projectDevice: 'p1' }, 'uid')).toBeTrue();
      expect(matchesQuery(item, { uids: 'd1,d2' }, 'uid')).toBeTrue();
      expect(matchesQuery(item, { search: 'router' }, 'uid')).toBeTrue();
    });

    it('excludes on mismatch or unknown filters', () => {
      expect(matchesQuery(item, { kind: 'y' }, 'uid')).toBeFalse();
      expect(matchesQuery(item, { projectDevices: ['p2'] }, 'uid')).toBeFalse();
      expect(matchesQuery(item, { unknownFilter: 'z' }, 'uid')).toBeFalse();
    });
  });

  describe('isNetworkError', () => {
    it('recognises connection errors only', () => {
      expect(isNetworkError(new TypeError('Failed to fetch'))).toBeTrue();
      expect(isNetworkError({ name: 'HttpErrorResponse', status: 0 })).toBeTrue();
      expect(isNetworkError({ status: 503 })).toBeTrue();
      expect(isNetworkError(new TypeError("Cannot read properties of undefined (reading 'x')"))).toBeFalse();
      expect(isNetworkError({ name: 'HttpErrorResponse', status: 400 })).toBeFalse();
      expect(isNetworkError({ name: 'AppwriteException', code: 409 })).toBeFalse();
    });
  });
});
